package hk.jimmy.wearmemory;
import android.app.*; import android.content.*; import android.os.*; import android.graphics.Color; import android.view.*; import android.widget.*; import java.io.*; import java.text.*; import java.util.*;
import android.media.*;import android.net.Uri;import android.provider.CalendarContract;
public class MainActivity extends Activity {
LinearLayout l;volatile AudioTrack playback;String importKind;
public void onCreate(Bundle b){super.onCreate(b);requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},1);ScheduleReceiver.schedule(this);home();}
void home(){l=Ui.page(this,new SimpleDateFormat("M 月 d 日",Locale.TRADITIONAL_CHINESE).format(new Date()));Ui.text(this,l,"一天的聲音，留低值得記住的事",16);String status=Ui.read(new File(getFilesDir(),"status.txt"));Ui.note(this,l,"最近分析",status.isEmpty()?"尚未有回顧。先匯入模型，再同步一段錄音。":status);Ui.button(this,l,"今日回顧",()->summaries(false));Ui.button(this,l,"每月回顧",()->summaries(true));Ui.button(this,l,"錄音與逐字稿",this::recordings);Ui.section(this,l,"整理記錄");Ui.button(this,l,"開始本機分析",()->{startForegroundService(new Intent(this,AnalysisService.class));toast("正在準備分析，可稍後查看進度");});Ui.section(this,l,"偏好設定");Ui.button(this,l,"AI 模型管理",this::models);Ui.button(this,l,"夜間與通知設定",this::settings);Ui.button(this,l,"匯出備份",()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/zip");i.putExtra(Intent.EXTRA_TITLE,"WearMemory_Backup_"+Ui.day(System.currentTimeMillis())+".zip");startActivityForResult(i,5);});Ui.text(this,l,"0.1.1 · 錄音保存在手機\n備份可選檔案選擇器內的 Drive；尚未支援自動備份",13);}
void summaries(boolean monthly){l=Ui.page(this,monthly?"每月回顧":"每日回顧");File[] files=Ui.dir(this,monthly?"monthly":"daily").listFiles((d,n)->n.endsWith(".txt"));if(files==null||files.length==0)Ui.text(this,l,"這段日子未有回顧\n完成錄音同步及本機分析後，內容會放在這裡",17);else{Arrays.sort(files,Comparator.reverseOrder());for(File f:files)Ui.button(this,l,f.getName().replace(".txt",""),()->detail(f));}Ui.button(this,l,"返回",this::home);}
void detail(File f){l=Ui.page(this,f.getName().replace(".txt",""));Ui.text(this,l,Ui.read(f),17);Ui.section(this,l,"日期與跟進");eventCards(f);Ui.text(this,l,"AI 內容需核對；日期及人名請返回逐字稿確認。",13);Ui.button(this,l,"建立日曆草稿",()->new AlertDialog.Builder(this).setMessage("請先核對摘要日期，再於日曆確認活動資料。").setPositiveButton("開啟日曆",(d,x)->{Intent i=new Intent(Intent.ACTION_INSERT,CalendarContract.Events.CONTENT_URI);i.putExtra(CalendarContract.Events.TITLE,"待確認活動");i.putExtra(CalendarContract.Events.DESCRIPTION,Ui.read(f));try{startActivity(i);}catch(Exception e){toast("未有可用日曆 App");}}).setNegativeButton("取消",null).show());Ui.button(this,l,"刪除此摘要",()->new AlertDialog.Builder(this).setMessage("刪除摘要？原始錄音仍保留。").setPositiveButton("刪除",(d,x)->{f.delete();home();}).setNegativeButton("取消",null).show());Ui.button(this,l,"返回",this::home);}
void eventCards(File summary){try{File ev=new File(Ui.dir(this,"events"),summary.getName().replace(".txt",".json"));org.json.JSONArray arr=new org.json.JSONArray(Ui.read(ev));for(int n=0;n<arr.length();n++){org.json.JSONObject ob=arr.getJSONObject(n);String title=ob.getString("title"),date=ob.getString("start");SimpleDateFormat fmt=new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.US);fmt.setLenient(false);long start=fmt.parse(date).getTime();Ui.button(this,l,"日期待確認 · "+title+" · "+date,()->{Intent i=new Intent(Intent.ACTION_INSERT,CalendarContract.Events.CONTENT_URI);i.putExtra(CalendarContract.Events.TITLE,title);i.putExtra(CalendarContract.EXTRA_EVENT_BEGIN_TIME,start);i.putExtra(CalendarContract.Events.EVENT_LOCATION,ob.optString("location"));i.putExtra(CalendarContract.Events.DESCRIPTION,"AI 草稿，請核對原錄音："+ob.optString("source"));try{startActivity(i);}catch(Exception e){toast("未有可用日曆 App");}});}}catch(Exception ignored){}}
void recordings(){l=Ui.page(this,"錄音記錄");File[] fs=Ui.dir(this,"audio").listFiles((d,n)->n.endsWith(".pcm"));if(fs==null||fs.length==0)Ui.note(this,l,"等待手錶同步","在手錶開始錄音，再停止錄音或等候一段完成，記錄就會顯示在這裡");if(fs!=null){Arrays.sort(fs,Comparator.reverseOrder());for(File f:fs)Ui.button(this,l,new SimpleDateFormat("MM-dd HH:mm",Locale.US).format(new Date(Long.parseLong(f.getName().replace(".pcm",""))))+" · "+f.length()/32000+" 秒",()->audio(f));}Ui.button(this,l,"返回",this::home);}
void audio(File f){l=Ui.page(this,"錄音詳情");Ui.text(this,l,Ui.read(new File(Ui.dir(this,"transcripts"),f.getName()+".txt")),17);Ui.button(this,l,"播放／停止",()->{if(playback!=null){try{playback.stop();}catch(Exception ignored){}playback=null;return;}new Thread(()->{try{AudioTrack track=new AudioTrack(3,16000,4,2,32000,1);playback=track;track.play();try(InputStream in=new FileInputStream(f)){byte[] bytes=new byte[16000];int n;while(playback==track&&(n=in.read(bytes))!=-1)track.write(bytes,0,n);}finally{if(playback==track)playback=null;track.release();}}catch(Exception e){runOnUiThread(()->toast(e.getMessage()));}}).start();});Ui.button(this,l,"刪除此錄音及分析資料",()->{if(AnalysisService.busy){toast("請等待分析完成後刪除");return;}new AlertDialog.Builder(this).setMessage("同時清除對應逐字稿、當日及當月摘要。此操作無法復原。").setPositiveButton("刪除",(d,x)->{String day=Ui.day(Long.parseLong(f.getName().replace(".pcm","")));f.delete();new File(Ui.dir(this,"transcripts"),f.getName()+".txt").delete();new File(Ui.dir(this,"events"),day+".json").delete();new File(Ui.dir(this,"daily"),day+".txt").delete();new File(Ui.dir(this,"monthly"),day.substring(0,7)+".txt").delete();recordings();}).setNegativeButton("取消",null).show();});Ui.button(this,l,"返回",this::recordings);}
void models(){l=Ui.page(this,"AI 模型");Ui.text(this,l,"語音：Whisper 多語言 ggml .bin\n分析：Qwen3 GGUF（建議 1.7B Q4）\n只支援相容架構；首次分析會驗證模型。模型以私有副本保存。",16);for(String k:new String[]{"asr","llm"}){File f=new File(Ui.dir(this,"models"),k+".model");Ui.section(this,l,k.equals("asr")?"語音轉文字":"摘要與日期分析");Ui.note(this,l,f.exists()?"已匯入":"尚未安裝",f.exists()?f.length()/1048576+" MB":"選擇相容的模型檔案");Ui.button(this,l,"還原上一版本",()->{if(AnalysisService.busy){toast("請等待分析完成");return;}File previous=new File(f+".previous");if(!previous.exists()){toast("沒有上一個版本");return;}File swap=new File(f+".swap");if(f.renameTo(swap)&&previous.renameTo(f)){swap.renameTo(previous);models();}else toast("還原未完成");});Ui.button(this,l,"匯入模型",()->{if(AnalysisService.busy){toast("分析途中暫時不能更換模型");return;}importKind=k;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,4);});}Ui.section(this,l,"下載模型");Ui.button(this,l,"取得 Whisper small 模型",()->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://huggingface.co/ggerganov/whisper.cpp/tree/main"))));Ui.button(this,l,"取得 Qwen3 GGUF 模型",()->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://huggingface.co/Qwen/Qwen3-1.7B-GGUF"))));Ui.button(this,l,"返回",this::home);}
protected void onActivityResult(int r,int s,Intent data){super.onActivityResult(r,s,data);if(r==5&&s==RESULT_OK&&data!=null){Uri target=data.getData();new Thread(()->{try(java.util.zip.ZipOutputStream zip=new java.util.zip.ZipOutputStream(getContentResolver().openOutputStream(target))){for(String folder:new String[]{"audio","transcripts","daily","monthly","events"}){File[] fs=Ui.dir(this,folder).listFiles();if(fs==null)continue;for(File file:fs){if(!file.isFile()||file.getName().endsWith(".tmp")||file.getName().endsWith(".part"))continue;zip.putNextEntry(new java.util.zip.ZipEntry(folder+"/"+file.getName()));try(InputStream input=new FileInputStream(file)){byte[] buf=new byte[65536];int n;while((n=input.read(buf))!=-1)zip.write(buf,0,n);}zip.closeEntry();}}runOnUiThread(()->toast("備份已匯出"));}catch(Exception e){runOnUiThread(()->toast("備份未完成："+e.getMessage()));}}).start();return;}if(r==4&&s==RESULT_OK&&data!=null){Uri uri=data.getData();String kind=importKind;new Thread(()->{try{File dest=new File(Ui.dir(this,"models"),kind+".model"),tmp=new File(dest+".tmp");try(InputStream in=getContentResolver().openInputStream(uri);FileOutputStream out=new FileOutputStream(tmp)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);out.getFD().sync();}try(java.io.RandomAccessFile rf=new java.io.RandomAccessFile(tmp,"r")){int magic=Integer.reverseBytes(rf.readInt());if((kind.equals("llm")&&magic!=0x46554747)||(kind.equals("asr")&&magic!=0x67676d6c)){tmp.delete();throw new IOException("模型格式不相容");}}File old=new File(dest+".previous");if(dest.exists()){old.delete();if(!dest.renameTo(old))throw new IOException("Cannot retain previous model");}if(!tmp.renameTo(dest)){old.renameTo(dest);throw new IOException("Import failed");}runOnUiThread(()->{toast("模型已匯入");models();});}catch(Exception e){runOnUiThread(()->toast(e.toString()));}}).start();}}
void settings(){l=Ui.page(this,"夜間與通知");android.content.SharedPreferences prefs=getSharedPreferences("settings",0);for(String key:new String[]{"night","morning"}){int mins=prefs.getInt(key,key.equals("night")?60:480);Ui.button(this,l,(key.equals("night")?"分析時間 ":"早晨通知 ")+String.format(Locale.US,"%02d:%02d",mins/60,mins%60),()->new TimePickerDialog(this,(v,h,m)->{prefs.edit().putInt(key,h*60+m).apply();ScheduleReceiver.schedule(this);settings();},mins/60,mins%60,true).show());}Switch sw=new Switch(this);sw.setText("排程分析只限充電時");sw.setTextColor(Ui.FG);sw.setPadding(Ui.dp(this,16),Ui.dp(this,16),Ui.dp(this,16),Ui.dp(this,16));sw.setMinHeight(Ui.dp(this,56));sw.setThumbTintList(android.content.res.ColorStateList.valueOf(Ui.ACC));sw.setChecked(prefs.getBoolean("charging",true));sw.setOnCheckedChangeListener((v,b)->prefs.edit().putBoolean("charging",b).apply());l.addView(sw);Ui.text(this,l,"背景排程可能延遲；未完成時早晨通知會顯示實際狀態。模型更新由你手動匯入。",14);Ui.button(this,l,"返回",this::home);}
void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
}